import pathlib, re
root = pathlib.Path(".venv/lib/python3.11/site-packages/streamlit/static/static/js")
pat = re.compile(r".{0,40}truncate.{0,260}", re.S)
seen=set()
for f in root.glob("*.js"):
    t=f.read_text(errors="ignore")
    for m in pat.findall(t):
        if re.search(r"webkit|WebkitLineClamp|overflow|ellipsis|clamp", m, re.I):
            s=m.strip()[:300]
            if s not in seen:
                seen.add(s); print("...",s,"\n")
EOF

